program='''from collections import Counter, deque

def _components(g, bg):
    h, w = len(g), len(g[0])
    seen = set(); comps = []
    for r in range(h):
        for c in range(w):
            v = g[r][c]
            if v == bg or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                p=q.popleft(); cells.append(p)
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr,nc=p[0]+dr,p[1]+dc
                    if 0<=nr<h and 0<=nc<w and g[nr][nc]==v and (nr,nc) not in seen:
                        seen.add((nr,nc)); q.append((nr,nc))
            comps.append((v,set(cells)))
    return comps

def _l_shapes(cells):
    # Find exact Ls made from one horizontal and one vertical straight arm.
    for r,c in cells:
        for dv in (-1,1):
            for dh in (-1,1):
                vert=[]; rr=r
                while (rr,c) in cells:
                    vert.append((rr,c)); rr+=dv
                horiz=[]; cc=c
                while (r,cc) in cells:
                    horiz.append((r,cc)); cc+=dh
                shape=set(vert)|set(horiz)
                if len(vert)>=2 and len(horiz)>=2 and shape==cells:
                    yield (r,c,dv,dh)

def transform(grid):
    g=[row[:] for row in grid]; h,w=len(g),len(g[0])
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    comps=_components(g,bg)
    # The L-shaped marker points along the continuation opposite its vertical arm.
    options=[]
    for color,cells in comps:
        for r,c,dv,dh in _l_shapes(cells):
            dr=-dv; rr=r+dr
            while 0<=rr<h and g[rr][c]==bg: rr+=dr
            if 0<=rr<h and g[rr][c]!=color:
                target_color=g[rr][c]
                target=next((cc for v,cc in comps if v==target_color and (rr,c) in cc),None)
                if target is not None:
                    options.append((len(cells),len(target),color,target))
    if options:
        # Prefer the marker whose ray reaches an object; among candidates use the longest L.
        _,_,color,target=max(options,key=lambda x:(x[0],x[1]))
        for r,c in target: g[r][c]=color
    return g
